"""Semantic-PMI regressions generated by this project through OCCT XCAF.

These files are deliberately self-written and self-read. They exercise the
owned extraction, unit-conversion, gap and identity contracts; they do not
establish exporter interoperability or external-corpus coverage.
"""

import math

import pytest

from cad_to_facts.artifact import register
from cad_to_facts.contract import verify_pmi_identity
from cad_to_facts.pmi import extract_pmi
from cad_to_facts.snapshot import read

from pmi_helpers import (
    write_pmi_dimensions,
    write_pmi_dimensions_in_unit,
    write_pmi_tolerances,
    write_pmi_tolerances_in_unit,
)


def _extract(path):
    artifact = register(path)
    snapshot = read(artifact)
    return artifact, snapshot, extract_pmi(artifact, snapshot)


def test_generated_dimensions_cover_deviation_limits_and_angular_values(tmp_path):
    path = tmp_path / "dimensions.step"
    write_pmi_dimensions(path)

    _, _, pmi = _extract(path)

    assert pmi.status == "ready"
    assert pmi.complete is True
    assert pmi.gaps == []
    assert pmi.inventory.dimension_entities == 4
    assert pmi.inventory.dimension_representation_entities == 4
    assert pmi.inventory.geometric_tolerance_entities == 0
    assert pmi.inventory.unsupported_category_counts == {}
    assert pmi.units == {"dimension_length": "mm", "dimension_angle": "rad"}
    assert len(pmi.unit_contexts) == 1
    assert pmi.unit_contexts[0].length == "mm"
    assert pmi.unit_contexts[0].angle == "rad"
    assert pmi.unit_contexts[0].dimension_representation_count == 4

    dimensions = [item for item in pmi.annotations if item.kind == "dimension"]
    assert len(dimensions) == 4
    thickness = next(
        item
        for item in dimensions
        if item.annotation_type == "size.thickness"
        and item.tolerance is not None
        and item.tolerance.form == "deviation_magnitudes"
    )
    assert thickness.value == pytest.approx(12.5)
    assert thickness.unit == "mm"
    assert thickness.tolerance.lower_deviation_magnitude == pytest.approx(0.1)
    assert thickness.tolerance.upper_deviation_magnitude == pytest.approx(0.1)
    assert thickness.tolerance.sign_convention == "not_reported_by_reader"

    limits = next(
        item
        for item in dimensions
        if item.annotation_type == "size.thickness"
        and item.tolerance is not None
        and item.tolerance.form == "limits"
    )
    assert limits.value == pytest.approx(20.0)
    assert limits.unit == "mm"
    assert limits.tolerance.lower_limit == pytest.approx(19.8)
    assert limits.tolerance.upper_limit == pytest.approx(20.2)

    angular = next(
        item
        for item in dimensions
        if item.annotation_type == "size.angular"
        and item.tolerance is not None
        and item.tolerance.form == "deviation_magnitudes"
    )
    assert angular.value == pytest.approx(math.radians(60.0))
    assert angular.unit == "rad"
    assert angular.tolerance.lower_deviation_magnitude == pytest.approx(0.01)
    assert angular.tolerance.upper_deviation_magnitude == pytest.approx(0.01)

    angular_limits = next(
        item
        for item in dimensions
        if item.annotation_type == "size.angular"
        and item.tolerance is not None
        and item.tolerance.form == "limits"
    )
    assert angular_limits.value == pytest.approx(math.radians(45.0))
    assert angular_limits.unit == "rad"
    assert angular_limits.tolerance.lower_limit == pytest.approx(math.radians(44.0))
    assert angular_limits.tolerance.upper_limit == pytest.approx(math.radians(46.0))

    assert all(item.link_status == "resolved" for item in dimensions)
    assert all(
        [entity.entity_id for entity in item.linked_entities] == ["solid:0"]
        for item in dimensions
    )
    sign = next(
        diagnostic
        for diagnostic in pmi.diagnostics
        if diagnostic.code == "PMI_TOLERANCE_SIGN_NOT_REPORTED"
    )
    assert sign.count == 2
    assert pmi.coverage.dimension_observed == 4
    assert pmi.coverage.dimension_annotations == 4
    assert pmi.coverage.dimension_with_value == 4
    assert pmi.coverage.link_resolved == 4
    assert pmi.coverage.discovery == "complete"
    assert verify_pmi_identity(pmi).pmi_id == pmi.pmi_id


def test_generated_tolerances_keep_datums_and_expose_datum_system_gap(tmp_path):
    path = tmp_path / "tolerances.step"
    write_pmi_tolerances(path)

    _, _, pmi = _extract(path)

    assert pmi.status == "partial"
    assert pmi.complete is False
    assert pmi.units == {
        "dimension_length": "mm",
        "dimension_angle": "rad",
        "geometric_tolerance_length": "mm",
    }
    assert pmi.inventory.dimension_entities == 1
    assert pmi.inventory.dimension_representation_entities == 1
    assert pmi.inventory.geometric_tolerance_entities == 2
    assert pmi.inventory.datum_entities == 3
    assert pmi.inventory.datum_feature_entities == 3
    assert pmi.inventory.datum_system_entities == 1
    assert pmi.inventory.unsupported_category_counts == {"datum_system": 1}

    tolerances = [
        item for item in pmi.annotations if item.kind == "geometric_tolerance"
    ]
    assert len(tolerances) == 2
    flatness = next(item for item in tolerances if item.annotation_type == "flatness")
    assert flatness.value == pytest.approx(0.05)
    assert flatness.unit == "mm"
    assert flatness.datums == []
    position = next(item for item in tolerances if item.annotation_type == "position")
    assert position.value == pytest.approx(0.2)
    assert position.unit == "mm"
    assert position.datums == ["A", "B", "C"]
    assert position.material_requirement_modifier == "m"

    datums = [item for item in pmi.annotations if item.kind == "datum"]
    assert sorted(item.semantic_name for item in datums) == ["A", "B", "C"]
    assert all(item.link_status == "resolved" for item in datums)
    assert all(
        [entity.entity_id for entity in item.linked_entities] == ["solid:0"]
        for item in tolerances + datums
    )

    unsupported = [
        gap for gap in pmi.gaps if gap.reason_code == "PMI_UNSUPPORTED_TYPE"
    ]
    assert len(pmi.gaps) == 1
    assert unsupported[0].annotation_type == "datum_system"
    assert pmi.coverage.dimension_observed == 1
    assert pmi.coverage.dimension_annotations == 1
    assert pmi.coverage.geometric_tolerance_observed == 2
    assert pmi.coverage.geometric_tolerance_annotations == 2
    assert pmi.coverage.geometric_tolerance_with_value == 2
    assert pmi.coverage.datum_observed == 3
    assert pmi.coverage.datum_annotations == 3
    assert pmi.coverage.datum_with_identification == 3
    assert pmi.coverage.link_resolved == 6
    assert pmi.coverage.link_unresolved == 0
    assert pmi.coverage.link_absent == 0
    assert pmi.coverage.discovery == "partial"
    assert {item.code for item in pmi.diagnostics} == {"PMI_COVERAGE_INCOMPLETE"}


def test_generated_inch_dimensions_preserve_declared_values(tmp_path):
    millimetres = tmp_path / "dimensions-mm.step"
    inches = tmp_path / "dimensions-inch.step"
    write_pmi_dimensions_in_unit(millimetres, inches, "INCH")

    _, _, pmi = _extract(inches)

    assert pmi.status == "ready"
    assert pmi.complete is True
    assert pmi.units == {"dimension_length": "in", "dimension_angle": "rad"}
    assert pmi.unit_contexts[0].length == "in"
    assert pmi.unit_contexts[0].angle == "rad"
    dimensions = [item for item in pmi.annotations if item.kind == "dimension"]

    thickness = next(
        item
        for item in dimensions
        if item.annotation_type == "size.thickness"
        and item.tolerance is not None
        and item.tolerance.form == "deviation_magnitudes"
    )
    assert thickness.value == pytest.approx(12.5)
    assert thickness.unit == "in"
    assert thickness.tolerance.lower_deviation_magnitude == pytest.approx(0.1)
    assert thickness.tolerance.upper_deviation_magnitude == pytest.approx(0.1)

    limits = next(
        item
        for item in dimensions
        if item.annotation_type == "size.thickness"
        and item.tolerance is not None
        and item.tolerance.form == "limits"
    )
    assert limits.value == pytest.approx(20.0)
    assert limits.unit == "in"
    assert limits.tolerance.lower_limit == pytest.approx(19.8)
    assert limits.tolerance.upper_limit == pytest.approx(20.2)

    angular = next(
        item
        for item in dimensions
        if item.annotation_type == "size.angular"
        and item.tolerance is not None
        and item.tolerance.form == "deviation_magnitudes"
    )
    assert angular.value == pytest.approx(math.radians(60.0))
    assert angular.unit == "rad"
    assert angular.tolerance.lower_deviation_magnitude == pytest.approx(0.01)

    angular_limits = next(
        item
        for item in dimensions
        if item.annotation_type == "size.angular"
        and item.tolerance is not None
        and item.tolerance.form == "limits"
    )
    assert angular_limits.value == pytest.approx(math.radians(45.0))
    assert angular_limits.unit == "rad"
    assert angular_limits.tolerance.lower_limit == pytest.approx(math.radians(44.0))
    assert angular_limits.tolerance.upper_limit == pytest.approx(math.radians(46.0))


