def test_generated_inch_geometric_tolerances_preserve_declared_values(tmp_path):
    millimetres = tmp_path / "tolerances-mm.step"
    inches = tmp_path / "tolerances-inch.step"
    write_pmi_tolerances_in_unit(millimetres, inches, "INCH")

    _, _, pmi = _extract(inches)

    assert pmi.status == "partial"
    assert pmi.complete is False
    assert pmi.units["dimension_length"] == "in"
    assert pmi.units["geometric_tolerance_length"] == "in"
    assert pmi.inventory.unsupported_category_counts == {"datum_system": 1}

    tolerances = [
        item for item in pmi.annotations if item.kind == "geometric_tolerance"
    ]
    flatness = next(item for item in tolerances if item.annotation_type == "flatness")
    assert flatness.value == pytest.approx(0.05)
    assert flatness.unit == "in"
    position = next(item for item in tolerances if item.annotation_type == "position")
    assert position.value == pytest.approx(0.2)
    assert position.unit == "in"
    assert position.datums == ["A", "B", "C"]
    assert position.material_requirement_modifier == "m"

    anchor = next(
        item
        for item in pmi.annotations
        if item.kind == "dimension" and item.annotation_type == "size.thickness"
    )
    assert anchor.value == pytest.approx(10.0)
    assert anchor.unit == "in"
